//! E2-M3 (D-DX4) — the single in-code command/flag registry.
//!
//! One source of truth for:
//!   - shell completions (bash / zsh / fish), generated by hand (no clap — I6);
//!   - the `jet` man page;
//!   - the no-args greeting and "did you mean" suggestions (E2101/E2102).
//!
//! The CLI surface is *not* language syntax, so per invariant I7 it does not
//! live in `src/syntax.rs` (Wave A added no CLI flags there; we match that).
//! It lives here so the generators, the greeting, and the typo-finder can never
//! drift apart.

// Stable IDs bind public command families to reviewed capability depth.
// CAPABILITY_CLAIMS:BEGIN
// CAPABILITY_CLAIM: claim.tooling-cli | One coherent beginner-first CLI.
// CAPABILITY_CLAIM: claim.ide-debug | Editor and debugger consume shared semantic facts.
// CAPABILITY_CLAIM: claim.format-test | Formatting and tests have deterministic workflows.
// CAPABILITY_CLAIM: claim.package-build | Build/package/environment commands have canonical ownership.
// CAPABILITY_CLAIMS:END

pub use crate::Syntax::edit_distance;
use crate::Syntax::BINARY_NAME;

/// One global flag that applies across commands.
pub struct FlagSpec {
    /// Long form, e.g. `--json` (always present).
    pub long: &'static str,
    /// One-line help, used in completions and the man page.
    pub help: &'static str,
}

/// One subcommand of `jet`.
pub struct CommandSpec {
    pub name: &'static str,
    /// One-line summary (man + completion description).
    pub summary: &'static str,
    /// Whether this is one of the three "commands that matter" shown when argv
    /// is flags-only with no subcommand (bare `jet` starts the REPL instead).
    pub headline: bool,
}

/// D-SHAPE6=A / D-CLI-SURFACE1=B / D-CLI-SURFACE2=A / D-CLI-SURFACE3=B:
/// authoritative noun-then-verb command registry.
pub struct CommandGroup {
    pub name: &'static str,
    pub summary: &'static str,
    pub actions: &'static [NestedCommandSpec],
    /// True when every subword of this group is modeled by `actions` — the
    /// bare group form and `<group> help` print the CLI-owned summary, and an
    /// unmodeled subword is E2101. False for `os` (D-CLI-SURFACE3=B): jetos
    /// owns a wider native verb surface (`check`/`build`/`switch`/…) that
    /// stays opaque to this registry, so only the migrated verbs
    /// (`push`/`bridge`/`services`/`config`) are modeled and everything else
    /// — including bare `jet os` and `jet os help` — falls through to the
    /// real `jet os` dispatcher unchanged.
    pub exhaustive: bool,
}

/// One canonical nested spelling and the real legacy dispatcher seam it reaches.
/// `HandlerKey::Hangar` keeps the group because that handler consumes the group word
/// itself (`hangar verify`, `hangar rollback`, `hangar generations`, `hangar du`, …).
pub struct NestedCommandSpec {
    pub name: &'static str,
    /// Canonical spelling after the group name. Multiple forms use one line each.
    pub usage: &'static str,
    pub summary: &'static str,
    pub handler: HandlerKey,
}

/// Closed set of real dispatcher seams reachable from nested commands.
/// Adding a handler requires updating this exhaustive mapping and its route test.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum HandlerKey {
    Publish, Yank, Keygen, Key, Vendor,
    Graph, Query, ExplainBuild, Impact, Dossier, Semindex, Expand, Unsafe, Schema, Codemod, Audit, Sbom, Bind, Live,
    Logs, Search, Info, Outdated,
    Hangar,
    GcReport,
    ProjectParts,
    Push, Bridge, Services, Config,
    Toolchain, Upgrade, Doctor, Completions, Man, Devtools, Lsp,
    Perf,
}

impl HandlerKey {
    pub const fn dispatch_word(self) -> &'static str {
        match self {
            Self::Publish => "publish", Self::Yank => "yank", Self::Keygen => "keygen",
            Self::Key => "key", Self::Vendor => "vendor", Self::Graph => "graph",
            Self::Query => "query", Self::ExplainBuild => "explain-build", Self::Impact => "impact",
            Self::Dossier => "dossier", Self::Semindex => "semindex", Self::Expand => "expand", Self::Unsafe => "unsafe",
            Self::Schema => "schema", Self::Codemod => "codemod", Self::Audit => "audit",
            Self::Sbom => "sbom", Self::Bind => "bind", Self::Live => "live",
            Self::Logs => "logs", Self::Search => "search", Self::Info => "info", Self::Outdated => "outdated",
            Self::Hangar => "hangar",
            Self::GcReport => "gc",
            Self::ProjectParts => "parts",
            Self::Push => "push", Self::Bridge => "bridge", Self::Services => "services", Self::Config => "config",
            Self::Toolchain => "toolchain",
            Self::Upgrade => "upgrade", Self::Doctor => "doctor", Self::Completions => "completions",
            Self::Man => "man", Self::Devtools => "devtools", Self::Lsp => "lsp",
            Self::Perf => "perf",
        }
    }

    pub const fn keeps_group(self) -> bool {
        matches!(self, Self::Hangar | Self::GcReport | Self::Perf)
    }
}

